//! Example demonstrating the env_kv! macro.
//!
//! Run with: cargo run -p tento_env --example env_kv_macro

use std::path::PathBuf;

use tento_env::{Env, EnvGroupBuilder, EnvGroupResult, FromEnvVar, env_kv};

// Standard form: struct name derived from env var key
env_kv!("DATABASE_URL", String);
env_kv!("LONA_JS", PathBuf);

// With default value: returns default if env var not set
env_kv!("PORT", u16, default = 8080);
env_kv!("DEBUG_MODE", bool, default = false);

// Named form: explicit struct name (for conflicts or custom names)
env_kv!(StripeSecretKey, "API_KEY", String);

#[allow(dead_code)]
#[derive(Debug)]
struct AppConfig {
  database_url: Env<DatabaseUrl>,
  lona_js: Env<LonaJs>,
  port: Env<Port>,
  debug_mode: Env<DebugMode>,
  stripe_key: Option<Env<StripeSecretKey>>,
}

impl AppConfig {
  fn from_env() -> EnvGroupResult<Self> {
    let mut builder = EnvGroupBuilder::new();

    let db = builder.require(
      DatabaseUrl::KEY,
      DatabaseUrl::from_env().map(|e| e.into_value()),
    );
    let lona_js = builder.require(LonaJs::KEY, LonaJs::from_env().map(|e| e.into_value()));

    // These have defaults, so they won't fail
    let port = Port::from_env().ok();
    let debug = DebugMode::from_env().ok();

    // Optional: Stripe key
    let stripe = builder.optional(
      StripeSecretKey::KEY,
      StripeSecretKey::from_env().map(|e| e.into_value()),
    );

    // Use the ::new() constructor generated by env_kv! for cleaner code
    builder.finish(|| {
      Some(AppConfig {
        database_url: DatabaseUrl::new(db.clone()?.0),
        lona_js: LonaJs::new(lona_js.clone()?.0),
        port: Port::new(port.clone()?.into_value().0),
        debug_mode: DebugMode::new(debug.clone()?.into_value().0),
        stripe_key: stripe.map(|s| StripeSecretKey::new(s.0)),
      })
    })
  }
}

fn main() {
  // SAFETY: Example code, single-threaded
  unsafe {
    std::env::set_var("DATABASE_URL", "postgres://localhost/mydb");
    std::env::set_var("LONA_JS", "/home/user/lona-js");
    std::env::set_var("PORT", "3000");
    std::env::set_var("DEBUG_MODE", "true");
    std::env::set_var("API_KEY", "sk_test_abc123");
  }

  let config = AppConfig::from_env().assert_envars();
  eprintln!("{:?}", config);

  // Cleanup
  unsafe {
    std::env::remove_var("DATABASE_URL");
    std::env::remove_var("LONA_JS");
    std::env::remove_var("PORT");
    std::env::remove_var("DEBUG_MODE");
    std::env::remove_var("API_KEY");
  }
}
